600	+/// The text pieces of a splittable message, each with its own key, or `None`
601	+/// when the message builds one joined text block (SMA-854).
602	+///
603	+/// The message has two or more text positions. The debug lines hold the
604	+/// reason and the lengths only, never the text.
605	+fn text_pieces(
606	+    content: &[ContentPart],
607	+    positions: &[(u32, Option<u64>)],
608	+    other_indexes: &[u32],
609	+) -> Option<Vec<(SortKey, String)>> {
610	+    let texts: Vec<&str> = content
611	+        .iter()
612	+        .filter_map(|p| match p {
613	+            ContentPart::Text { text } if !text.is_empty() => Some(text.as_str()),
614	+            _ => None,
615	+        })
616	+        .collect();
617	+    let text = match texts.as_slice() {
618	+        [] => return None,
619	+        [text] => *text,
620	+        _ => {
621	+            tracing::debug!(
622	+                target: "paigasus::anthropic::translate",
623	+                reason = "several text parts",
624	+                positions = positions.len(),
625	+                text_bytes = texts.iter().map(|t| t.len()).sum::<usize>(),
626	+                "anthropic text does not split; one joined block",
627	+            );
628	+            return None;
629	+        }
630	+    };
631	+    let cuts = match split_plan(text, positions, other_indexes) {
632	+        Ok(cuts) => cuts,
633	+        Err(reason) => {
634	+            tracing::debug!(
635	+                target: "paigasus::anthropic::translate",
636	+                ?reason,
637	+                positions = positions.len(),
638	+                text_bytes = text.len(),
639	+                "anthropic text does not split; one joined block",
640	+            );
641	+            return None;
642	+        }
643	+    };
644	+    // The API rejects an empty text block, so an empty piece gives no block.
645	+    // `split_plan` checked every range. If a slice still fails, the message
646	+    // builds one joined block, so that no piece of the text is lost.
647	+    cuts.into_iter()
648	+        .filter(|(_, range)| !range.is_empty())
649	+        .map(|(index, range)| {
650	+            text.get(range)
651	+                .map(|piece| (SortKey::At(u64::from(index), 1), piece.to_owned()))
652	+        })
653	+        .collect()
654	+}
